import { NextResponse } from "next/server";
import Experience from "../../../../experience.model.js";
import { connectDB } from "../../../../db.js";

export async function GET(req: Request, { params }: { params: { id: string } }) {
  await connectDB();
  try {
    const experience = await Experience.findById(params.id);
    if (!experience) {
      return NextResponse.json({ message: "Experience not found" }, { status: 404 });
    }
    return NextResponse.json(experience);
  } catch (err) {
    return NextResponse.json({ message: "Failed to fetch experience", error: err }, { status: 500 });
  }
}

export async function PUT(req: Request, { params }: { params: { id: string } }) {
  await connectDB();
  try {
    const body = await req.json();
    const updated = await Experience.findByIdAndUpdate(params.id, body, { new: true });
    if (!updated) {
      return NextResponse.json({ message: "Experience not found" }, { status: 404 });
    }
    return NextResponse.json(updated);
  } catch (err) {
    return NextResponse.json({ message: "Failed to update experience", error: err }, { status: 500 });
  }
}

export async function DELETE(req: Request, { params }: { params: { id: string } }) {
  await connectDB();
  try {
    const deleted = await Experience.findByIdAndDelete(params.id);
    if (!deleted) {
      return NextResponse.json({ message: "Experience not found" }, { status: 404 });
    }
    return NextResponse.json({ message: "Experience deleted successfully" });
  } catch (err) {
    return NextResponse.json({ message: "Failed to delete experience", error: err }, { status: 500 });
  }
}
